function WarehouseMark() {
  return (
    <g className="fill-text">
      <path className="fill-brand dark:fill-accent" d="M7 23.4a3 3 0 0 1 1.5-2.6L29.5 8.4a4.9 4.9 0 0 1 5 0l21 12.4a3 3 0 0 1 1.5 2.6V27H7Z" />
      <rect x="7" y="33" width="21" height="23" rx="3" />
      <rect x="35" y="33" width="22" height="8.5" rx="2.2" />
      <rect x="35" y="47" width="22" height="9" rx="2.2" />
    </g>
  );
}

export function LogoMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 64 64" className={cn("size-8 shrink-0", className)} role="img" aria-label={BRAND.nameFa}>
      <WarehouseMark />
    </svg>
  );
}

export function Logo({ className, compact }: { className?: string; compact?: boolean }) {
  if (compact) return <LogoMark className={className} />;
  return (
    <span className={cn("inline-flex shrink-0 items-center", className)}>
      <span className="sr-only">{BRAND.nameFa}</span>
      <svg viewBox="0 0 338 118" className="h-9 w-auto fill-text" aria-hidden="true">
        <path d={WORDMARK} transform="translate(10 16) scale(.655) translate(-5.605 83.193)" />
        <g transform="translate(245 11) scale(1.29)"><WarehouseMark /></g>
      </svg>
    </span>
  );
}

/** نام‌نوشتهٔ بدون نشان برای لایه‌های دورخط و رنگ پانویس. */
export function BrandWordmark({ className, gradient = false }: { className?: string; gradient?: boolean }) {
  const id = useId();
  return (
    <svg viewBox="3 -86 331 135" className={className} aria-hidden="true">
      <defs>
        {gradient ? (
          <linearGradient id={id} x1="100%" x2="0%">
            <stop stopColor="var(--brand)" />
            <stop offset="1" stopColor="var(--accent)" />
          </linearGradient>
        ) : (
          // دورخط از سطح یکپارچهٔ حروف ساخته می‌شود تا اتصال حروف خط اضافه نداشته باشد.
          <filter id={id}>
            <feMorphology in="SourceAlpha" operator="dilate" radius="0.8" result="expanded" />
            <feComposite in="expanded" in2="SourceAlpha" operator="out" result="outline" />
            <feFlood floodColor="var(--border-strong)" result="color" />
            <feComposite in="color" in2="outline" operator="in" />
          </filter>
        )}
      </defs>
      <path d={WORDMARK} fill={gradient ? `url(#${id})` : "#fff"} filter={gradient ? undefined : `url(#${id})`} />
    </svg>
  );
}
